using System;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Globalization;
namespace FssLauncher {
 public class AccountDialog:Form {
  public bool RequestPending{get{return busy;}}public event EventHandler AuthenticationCompleted;
  readonly LauncherForm launcher;readonly bool signup;readonly Dictionary<string,TextBox> fields=new Dictionary<string,TextBox>();readonly CheckBox remember=new CheckBox(),terms=new CheckBox();readonly ComboBox country=new ComboBox();readonly Label error=new Label();readonly FlatAction submit=new FlatAction();bool busy;readonly Timer readiness=new Timer();
  public AccountDialog(LauncherForm parent,bool registration){launcher=parent;signup=registration;Icon=Branding.AppIcon();Text=signup?"Create your Fortnite Classic account":"Sign in to Fortnite Classic";BackColor=Color.FromArgb(32,32,32);ForeColor=Color.White;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.None;MaximizeBox=MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(460,signup?820:570);var close=new FlatAction{Text="\u00d7",BackColor=BackColor};close.SetBounds(420,5,35,30);close.Click+=delegate{Close();};Controls.Add(close);MouseDown+=delegate(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Left&&e.Y<35){Native.ReleaseCapture();Native.SendMessage(Handle,0xA1,new IntPtr(2),IntPtr.Zero);}};
   var logo=new PictureBox{Image=Branding.Logo,SizeMode=PictureBoxSizeMode.Zoom};logo.SetBounds(35,15,55,65);Controls.Add(logo);LabelAt(signup?"CREATE ACCOUNT":"SIGN IN",35,85,390,35,16,FontStyle.Bold);int y=140;
   if(signup){LabelAt("COUNTRY",35,y,390,20,9,FontStyle.Regular);country.SetBounds(35,y+24,390,30);country.Name="country";country.DropDownStyle=ComboBoxStyle.DropDownList;country.FlatStyle=FlatStyle.Flat;country.DrawMode=DrawMode.OwnerDrawFixed;country.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(var brush=new SolidBrush(Color.FromArgb(49,49,49)))e.Graphics.FillRectangle(brush,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,country.Items[e.Index].ToString(),Font,e.Bounds,Color.White,TextFormatFlags.VerticalCenter);};country.BackColor=Color.FromArgb(49,49,49);country.ForeColor=Color.White;var names=new SortedDictionary<string,string>();foreach(var culture in CultureInfo.GetCultures(CultureTypes.SpecificCultures)){try{var region=new RegionInfo(culture.Name);names[region.EnglishName]=region.TwoLetterISORegionName;}catch(ArgumentException){}}foreach(var pair in names)country.Items.Add(new Country{Text=pair.Key,Code=pair.Value});Controls.Add(country);y+=65;foreach(string name in new[]{"FIRST NAME","LAST NAME","DISPLAY NAME"}){Field(name,y,false);y+=65;}}
   Field("EMAIL ADDRESS",y,false);y+=65;Field("PASSWORD",y,true);y+=65;if(signup){Field("CONFIRM PASSWORD",y,true);y+=65;terms.Name="terms";terms.Text="I agree to the account Terms of Service";terms.SetBounds(35,y,390,25);Controls.Add(terms);var link=new LinkLabel{Text="Read account terms",LinkColor=Color.Silver};link.SetBounds(35,y+27,390,23);link.LinkClicked+=delegate{MessageBox.Show(this,"Fortnite Classic local account terms (version local-accounts-1)\n\nYour account is stored on the Server Studio backend you connect to. Your name and email identify your account; passwords are hashed. The backend operator controls this database. Use this service only with software and content you are authorized to use. Keep your credentials private.\n\nThis community project is not affiliated with Epic Games.","Account Terms",MessageBoxButtons.OK,MessageBoxIcon.Information);};Controls.Add(link);y+=60;}else{remember.Name="remember";remember.Text="REMEMBER ME";remember.SetBounds(35,y,390,25);Controls.Add(remember);y+=38;}
   error.Name="error";error.ForeColor=Color.FromArgb(239,145,136);error.SetBounds(35,y,390,48);Controls.Add(error);y+=52;submit.Name="submit";submit.Text=signup?"CREATE ACCOUNT":"SIGN IN";submit.SetBounds(35,y,390,44);Controls.Add(submit);AcceptButton=submit;submit.Click+=async delegate{if(busy)return;error.Text="";if(signup&&(fields["PASSWORD"].Text!=fields["CONFIRM PASSWORD"].Text||!terms.Checked||country.SelectedItem==null)){error.Text="Confirm your password, choose a country, and accept the terms.";return;}busy=true;submit.Enabled=false;bool success=false;try{object body=signup?(object)new{launcher=true,country=((Country)country.SelectedItem).Code,firstName=fields["FIRST NAME"].Text,lastName=fields["LAST NAME"].Text,displayName=fields["DISPLAY NAME"].Text,email=fields["EMAIL ADDRESS"].Text,password=fields["PASSWORD"].Text,termsAccepted=terms.Checked,remember=false}:new{email=fields["EMAIL ADDRESS"].Text,password=fields["PASSWORD"].Text,remember=remember.Checked};await launcher.Authenticate(signup?"register":"login",body,remember.Checked);success=true;}catch(Exception ex){error.Text=ex.Message;}finally{fields["PASSWORD"].Clear();if(signup)fields["CONFIRM PASSWORD"].Clear();busy=false;submit.Enabled=true;}if(success){if(AuthenticationCompleted!=null)AuthenticationCompleted(this,EventArgs.Empty);DialogResult=DialogResult.OK;Close();}};
   y+=56;if(!signup){var forgot=new LinkLabel{Text="FORGOT YOUR PASSWORD?",LinkColor=Color.Silver};forgot.SetBounds(35,y,390,25);forgot.LinkClicked+=delegate{error.Text="Password recovery is not configured. Contact your backend operator.";};Controls.Add(forgot);y+=35;}
   var switchLink=new LinkLabel{Text=signup?"Already have an account? SIGN IN":"Don't have an account? SIGN UP",LinkColor=Color.Silver};switchLink.SetBounds(35,y,390,30);switchLink.LinkClicked+=delegate{if(busy)return;Hide();using(var next=new AccountDialog(launcher,!signup))next.ShowDialog(Owner);if(launcher.Profile!=null)Close();else Show();};Controls.Add(switchLink);readiness.Interval=300;readiness.Tick+=delegate{submit.Enabled=!busy&&launcher.State==StudioState.Online;};submit.Enabled=launcher.State==StudioState.Online;readiness.Start();FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy)e.Cancel=true;};
  }
  protected override void Dispose(bool disposing){if(disposing)readiness.Dispose();base.Dispose(disposing);}
  void LabelAt(string text,int x,int y,int width,int height,float size,FontStyle style){var label=new Label{Text=text,Font=new Font("Segoe UI",size,style)};label.SetBounds(x,y,width,height);Controls.Add(label);}
  void Field(string name,int y,bool secret){LabelAt(name,35,y,390,20,9,FontStyle.Regular);var input=new TextBox{BackColor=Color.FromArgb(49,49,49),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle,UseSystemPasswordChar=secret,MaxLength=secret?72:254};input.SetBounds(35,y+24,390,30);input.Name=name;fields.Add(name,input);Controls.Add(input);}
